/**
 * Completeness invariant for the INTERNAL WRITE API catalog — NO database.
 *
 * The admin « API interne » tab + API.md present every server action from
 * src/lib/api-auth/internal-api-catalog.ts (generated by
 * scripts/gen-internal-api-catalog.mjs). This test re-derives the exported
 * server-action set from disk and asserts the committed catalog lists EXACTLY that
 * set — so a new server action can't ship undocumented, and a deleted one can't
 * linger (mirrors how route-invariants enforces route-catalog ⇔ disk). It also
 * checks every permission label is a real RBAC registry key (the labels were once
 * hand-written and advertised modules that don't exist — system_content, blog,
 * aide, business…), that the labels still cover each file's literal guards, and
 * that no mutating action is labelled kind "read". If this fails:
 * `node scripts/gen-internal-api-catalog.mjs` and recommit.
 *
 * Run:
 *   pnpm exec tsx --conditions=react-server src/lib/db/tests/internal-api-catalog.test.ts
 */
import { readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";

import ts from "typescript";

import {
  INTERNAL_ACTION_NAMES,
  INTERNAL_API_CATALOG,
} from "@/lib/api-auth/internal-api-catalog";
import { isValidPermissionKey } from "@/lib/rbac/registry";

let passed = 0;
let failed = 0;
function check(label: string, cond: boolean) {
  if (cond) {
    passed++;
    console.log(`  ✓ ${label}`);
  } else {
    failed++;
    console.error(`  ✗ ${label}`);
  }
}

const ACTIONS_DIR = join(process.cwd(), "src", "lib", "actions");
// Every export of a "use server" file is a callable server action (Next only
// allows async functions there), whatever its name — so match any identifier,
// not just `*Action`, or a misnamed endpoint escapes the catalogue.
const EXPORT_RE = /^export\s+(?:async\s+)?(?:function|const)\s+([a-zA-Z0-9_]+)\b/gm;
const USE_SERVER_RE = /^\s*(?:(?:\/\/[^\n]*|\/\*[\s\S]*?\*\/)\s*)*["']use server["']/;

/** Pseudo-scopes the generator emits besides real `<module>:<action>` keys. */
const PSEUDO_SCOPES = new Set(["public", "session", "session/public"]);
/** Splits a label into its keys: " · " between checks, " | " between alternatives. */
const tokens = (label: string) => label.split(/\s*[·|]\s*/);

/** Mutating verb prefixes that must never be classified kind "read". */
const WRITE_VERB = /^(toggle|set|update|transition|bulk|issue|create|delete|save|add|remove|apply|assign|mark)(?=[A-Z])/;

type ServerFile = { file: string; src: string };

function serverFiles(): ServerFile[] {
  return readdirSync(ACTIONS_DIR)
    .filter((f) => f.endsWith(".ts"))
    .map((file) => ({ file, src: readFileSync(join(ACTIONS_DIR, file), "utf8") }))
    .filter((f) => USE_SERVER_RE.test(f.src));
}

function diskActions(files: ServerFile[]): Set<string> {
  const names = new Set<string>();
  for (const { src } of files) {
    for (const m of src.matchAll(EXPORT_RE)) names.add(m[1]);
  }
  return names;
}

/**
 * The LITERAL guard keys of a file (AST, so comments never count):
 * requirePermission("m", "a"), permissionSetAllows(_, "m", "a") and
 * requirePermissionAny([{ module: "m", action: "a" }, …]). An independent,
 * deliberately simple re-derivation — dynamic guards are the generator's job.
 */
function literalGuardKeys(file: string, src: string): string[] {
  const sf = ts.createSourceFile(file, src, ts.ScriptTarget.Latest, true);
  const keys = new Set<string>();
  const str = (n: ts.Node | undefined) =>
    n && (ts.isStringLiteral(n) || ts.isNoSubstitutionTemplateLiteral(n)) ? n.text : null;
  const pair = (m: ts.Node | undefined, a: ts.Node | undefined) => {
    const mod = str(m);
    const act = str(a);
    if (mod && act) keys.add(`${mod}:${act}`);
  };
  const visit = (n: ts.Node) => {
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression)) {
      const [a0, a1, a2] = n.arguments;
      if (n.expression.text === "requirePermission") pair(a0, a1);
      else if (n.expression.text === "permissionSetAllows") pair(a1, a2);
      else if (n.expression.text === "requirePermissionAny" && a0 && ts.isArrayLiteralExpression(a0)) {
        for (const el of a0.elements) {
          if (!ts.isObjectLiteralExpression(el)) continue;
          const prop = (k: string) =>
            el.properties.find((p): p is ts.PropertyAssignment => ts.isPropertyAssignment(p) && p.name.getText(sf) === k)
              ?.initializer;
          pair(prop("module"), prop("action"));
        }
      }
    }
    ts.forEachChild(n, visit);
  };
  visit(sf);
  return [...keys];
}

/** Does a domain label cover `module:action` (exactly, or via `module:*`)? */
function covers(label: string, key: string): boolean {
  const t = tokens(label);
  return t.includes(key) || t.includes(`${key.split(":")[0]}:*`);
}

function main() {
  const files = serverFiles();
  const disk = diskActions(files);
  const catalog = new Set(INTERNAL_ACTION_NAMES);

  console.log("internal-api-catalog ⇔ disk:");
  check(`disk has actions (${disk.size})`, disk.size > 0);
  check(`catalog non-empty (${catalog.size})`, catalog.size > 0);

  const missing = [...disk].filter((n) => !catalog.has(n)).sort();
  check(
    `every disk action is catalogued${missing.length ? ` — MISSING: ${missing.join(", ")}` : ""}`,
    missing.length === 0,
  );

  const extra = [...catalog].filter((n) => !disk.has(n)).sort();
  check(
    `no phantom catalog actions${extra.length ? ` — EXTRA: ${extra.join(", ")}` : ""}`,
    extra.length === 0,
  );

  // No duplicate action names across the whole catalog (each is globally unique).
  const dup = INTERNAL_ACTION_NAMES.filter((n, i) => INTERNAL_ACTION_NAMES.indexOf(n) !== i);
  check(`no duplicate catalogued actions${dup.length ? ` — ${[...new Set(dup)].join(", ")}` : ""}`, dup.length === 0);

  // Every domain references a real action file + carries a non-empty label/permission.
  const domains = INTERNAL_API_CATALOG.flatMap((g) => g.domains);
  const badDomain = domains.filter(
    (d) => !d.file.startsWith("src/lib/actions/") || !d.label || !d.permission || d.actions.length === 0,
  );
  check(`every domain is well-formed${badDomain.length ? ` — ${badDomain.map((d) => d.file).join(", ")}` : ""}`, badDomain.length === 0);

  // A non-`*Action` export is still a public endpoint — flag it for a rename.
  const misnamed = [...disk].filter((n) => !n.endsWith("Action")).sort();
  if (misnamed.length) console.warn(`  ⚠ server actions not named *Action (catalogued, rename them): ${misnamed.join(", ")}`);

  console.log("\npermission labels ⇔ RBAC registry:");
  const actions = domains.flatMap((d) => d.actions.map((a) => ({ ...a, file: d.file })));
  const noPerm = actions.filter((a) => !a.permission);
  check(`every action carries a permission label${noPerm.length ? ` — ${noPerm.map((a) => a.name).join(", ")}` : ""}`, noPerm.length === 0);

  const badKey = (label: string) => tokens(label).filter((t) => !PSEUDO_SCOPES.has(t) && !isValidPermissionKey(t));
  const badActionKeys = actions.flatMap((a) => badKey(a.permission).map((t) => `${a.name}: ${t}`));
  check(
    `every action permission is a registry key or pseudo-scope${badActionKeys.length ? ` — ${badActionKeys.join(", ")}` : ""}`,
    badActionKeys.length === 0,
  );
  const badDomainKeys = domains.flatMap((d) => badKey(d.permission).map((t) => `${d.file}: ${t}`));
  check(
    `every domain permission is a registry key or pseudo-scope${badDomainKeys.length ? ` — ${badDomainKeys.join(", ")}` : ""}`,
    badDomainKeys.length === 0,
  );

  // The domain label is the union of its actions' keys.
  const uncovered = domains.flatMap((d) =>
    d.actions.flatMap((a) =>
      tokens(a.permission)
        .filter((t) => !covers(d.permission, t))
        .map((t) => `${d.file} ⊅ ${a.name}: ${t}`),
    ),
  );
  check(`every domain label covers its actions' keys${uncovered.length ? ` — ${uncovered.join(", ")}` : ""}`, uncovered.length === 0);

  // Drift: a guard edited on disk without regenerating must fail here.
  const byFile = new Map(domains.map((d) => [d.file.replace("src/lib/actions/", ""), d.permission]));
  const stale = files.flatMap(({ file, src }) => {
    const label = byFile.get(file);
    if (label === undefined) return [];
    return literalGuardKeys(file, src)
      .filter((k) => !covers(label, k))
      .map((k) => `${file}: ${k}`);
  });
  check(`catalog labels cover every literal guard on disk${stale.length ? ` — STALE: ${stale.join(", ")}` : ""}`, stale.length === 0);

  console.log("\naction kinds:");
  const writeVerbs = actions.filter((a) => WRITE_VERB.test(a.name));
  check(`write-verb actions found (${writeVerbs.length})`, writeVerbs.length > 0);
  // `issue…` once matched a bare `^is` read prefix, and `…Status` / `…Active`
  // suffixes made transitionOrderStatus / togglePromotionActive "read".
  const readWrites = writeVerbs.filter((a) => a.kind === "read").map((a) => a.name);
  check(`no mutating action is kind "read"${readWrites.length ? ` — ${readWrites.join(", ")}` : ""}`, readWrites.length === 0);

  console.log(`\n=== done: ${passed} passed, ${failed} failed === (disk=${disk.size}, catalog=${catalog.size})`);
  if (failed > 0) process.exit(1);
}

main();
